/bin/bash -lc "python3 - <<'PY'
import urllib.request, urllib.error
url='http://localhost:3100/product'
tree='[\"\",{\"children\":[\"__PAGE__\",{}]},null,null,true]'
variants={
  'default': {'RSC':'1','Next-Router-Prefetch':'1','Next-Router-State-Tree':tree},
  'full': {'RSC':'1','Next-Router-Prefetch':'1','Next-Router-State-Tree':tree,'Next-Router-Segment-Prefetch':'/product'},
  'navigation': {'RSC':'1','Next-Router-State-Tree':tree}
}
for label,headers in variants.items():
    req=urllib.request.Request(url,headers=headers)
    try:
        with urllib.request.urlopen(req) as res:
            data=res.read().decode('utf-8',errors='replace')
            print(label,res.status,len(data),'Compact Widget' in data,'Loading related products' in data,res.headers.get('location'))
    except urllib.error.HTTPError as e:
        print(label,e.code,e.headers.get('location'))
PY"

